  "Are you sure you want to permanently delete this subscription? This action cannot be undone.": "Sind Sie sicher, dass Sie dieses Abonnement endgültig löschen möchten? Diese Aktion kann nicht rückgängig gemacht werden.",
  "As a student, I couldn't just drop €380 for new glasses every two years. With Lensly I pay €29 a month and get a new pair every year. Last week my frame got damaged — the replacement arrived in 4 days.": "Als Studentin konnte ich mir alle zwei Jahre nicht einfach €380 für eine neue Brille leisten. Mit Lensly zahle ich 29 € im Monat und bekomme jedes Jahr ein neues Paar. Letzte Woche wurde mein Gestell beschädigt — der Ersatz war in 4 Tagen da.",
  "As a student, paying €400 upfront at traditional opticians was impossible. Lensly's €29 flat monthly rate is insanely cheap and completely hassle-free. Got my second pair last week—super clean lenses and fast shipping!": "Als Studentin war es unmöglich, beim herkömmlichen Optiker €400 auf einmal zu bezahlen. Lenslys €29 Pauschalpreis pro Monat ist unglaublich günstig und völlig unkompliziert. Habe letzte Woche mein zweites Paar bekommen — super saubere Gläser und schneller Versand!",
