  "Because prescription eyewear is individually manufactured, delivery times may vary depending on production requirements, supplier availability, laboratory processing times, and shipping conditions.": "Da Korrektionsbrillen individuell hergestellt werden, können die Lieferzeiten je nach Produktionsanforderungen, Lieferantenverfügbarkeit, Laborbearbeitungszeiten und Versandbedingungen variieren.",
  "Because the first glasses are custom-made according to the Customer's individual prescription, measurements, and selected frame, the Customer may request changes before final confirmation of the first glasses order.": "Da die erste Brille individuell nach der individuellen Sehstärke, den Maßen und der gewählten Fassung des Kunden angefertigt wird, kann der Kunde vor der endgültigen Bestätigung der Bestellung der ersten Brille Änderungen anfordern.",
