  "Delays caused by missing customer information, supplier availability, laboratory processing times, shipping conditions, or circumstances outside Lensly's reasonable control do not remove Lensly's obligation to fulfil the agreed eyewear benefit.": "Verzögerungen, die durch fehlende Kundeninformationen, Lieferantenverfügbarkeit, Laborbearbeitungszeiten, Versandbedingungen oder Umstände außerhalb der angemessenen Kontrolle von Lensly verursacht werden, entbinden Lensly nicht von der Verpflichtung, den vereinbarten Brillenvorteil zu erfüllen.",
  "Delays caused by missing, incomplete, or incorrect customer information may delay production.": "Verzögerungen aufgrund fehlender, unvollständiger oder falscher Kundeninformationen können zu Produktionsverzögerungen führen.",
