  "Einmalkauf im Handel:": "Einmalkauf im Handel:",
  "Elegant transparent round frame crafting a modern, intellectual look. Soft keyhole bridge for maximum all-day comfort.": "Eleganter, transparenter runder Rahmen für einen modernen, intellektuellen Look. Weicher Schlüssellochsteg für maximalen Komfort den ganzen Tag.",
