  "Enter the email address or tracking ID used when submitting your frame request or subscription.": "Geben Sie die E-Mail-Adresse oder Tracking-ID ein, die Sie beim Senden Ihrer Rahmenanfrage oder Ihres Abonnements verwendet haben.",
  "Enter your Pupillary Distance (PD) for a more accurate fit. Be sure to double check your frame's dimensions before ordering your glasses.": "Geben Sie für eine genauere Anpassung Ihren Pupillenabstand (PD) ein. Überprüfen Sie unbedingt die Abmessungen Ihres Rahmens, bevor Sie Ihre Brille bestellen.",
  "Enter your subscription email address or contract ID to manage your glasses, track live orders, and review prescriptions.": "Geben Sie Ihre Abonnement-E-Mail-Adresse oder Vertrags-ID ein, um Ihre Brillen zu verwalten, Live-Bestellungen zu verfolgen und Rezepte zu überprüfen.",
