  "Every 12 months you receive a complete new pair with updated prescription values and your choice of frame.": "Every 12 months you receive a complete new pair with updated prescription values and your choice of frame.",
  "Every contract year you receive a complete new pair of prescription glasses with fresh anti-reflective coatings and updated diopters to ensure optimal visual health.": "Jedes Vertragsjahr erhalten Sie eine komplett neue Korrektionsbrille mit frischen Antireflexbeschichtungen und aktualisierten Dioptrien, um eine optimale Sehgesundheit zu gewährleisten.",
  "Every single year": "Jedes einzelne Jahr",
  "Every year, a new pair of prescription glasses — delivered straight to your door. Break them? Three free replacements included.": "Jedes Jahr eine neue Korrektionsbrille — direkt zu dir nach Hause. Brichst du sie? Drei kostenlose Ersatzpaare inklusive.",
