  "Fassungsbruch, tiefe Kratzer oder nachgewiesene Sehstärkenänderung innerhalb des Jahres? Ihr Tarif umfasst ein Kontingent von bis zu drei Ersatzanfragen pro Vertragsjahr gemäß Tarifbedingungen.": "Fassungsbruch, tiefe Kratzer oder nachgewiesene Sehstärkenänderung innerhalb des Jahres? Ihr Tarif umfasst ein Kontingent von bis zu drei Ersatzanfragen pro Vertragsjahr gemäß Tarifbedingungen.",
  "Fassungsbruch, tiefe Kratzer oder verordnete Dioptrienänderungen innerhalb des Jahres werden bis zu dreimal tarifgemäß abgedeckt.": "Fassungsbruch, tiefe Kratzer oder verordnete Dioptrienänderungen innerhalb des Jahres werden bis zu dreimal tarifgemäß abgedeckt.",
  "Feedbacks": "Bewertungen",
  "Feminine winged silhouette in high-gloss piano black. A sophisticated retro statement piece.": "Feminine Flügelsilhouette in hochglänzendem Pianoschwarz. Ein raffiniertes Retro-Statement-Stück.",
