  "Issues caused by incorrect customer-provided information or incorrect customer selection may not qualify for free replacement.": "Probleme, die durch falsche vom Kunden bereitgestellte Informationen oder eine falsche Kundenauswahl verursacht werden, haben möglicherweise keinen Anspruch auf kostenlosen Ersatz.",
