  "Lenses being custom surfaced.": "Korrekturgläser werden maßgefertigt.",
  "Lensly Care": "Lensly Care",
  "Lensly Care is a vision subscription service providing customers with access to custom-made prescription eyewear benefits.": "Lensly Care ist ein Seh-Abonnementdienst, der Kunden Zugang zu maßgeschneiderten Korrekturbrillen bietet.",
  "Lensly Continuous Care:": "Lensly Kontinuierliche Pflege:",
  "Lensly Signature Frame Collection": "Lensly Signature-Rahmenkollektion",
  "Lensly Standard Plan": "Lensly Standardplan",
  "Lensly Vision Care Agreement": "Lensly Vision Care Agreement",
  "Lensly is a small independent team focused on making quality prescription eyewear affordable and accessible across Europe. We work directly with certified optical labs to cut out retail markups.": "Lensly ist ein kleines, unabhängiges Team, das sich darauf konzentriert, hochwertige Korrektionsbrillen in ganz Europa erschwinglich und zugänglich zu machen. Wir arbeiten direkt mit zertifizierten Optiklaboren zusammen, um Händlerspannen zu vermeiden.",
  "Lensly manufactures prescription eyewear according to the information and specifications provided by the Customer.": "Lensly manufactures prescription eyewear according to the information and specifications provided by the Customer.",
  "Lensly provides custom-made prescription eyewear through selected optical suppliers and laboratories.": "Lensly bietet maßgeschneiderte Korrektionsbrillen über ausgewählte Optiklieferanten und Labore an.",
  "Lensly provides up to three (3) approved replacement services per contract year.": "Lensly stellt pro Vertragsjahr bis zu drei (3) genehmigte Ersatzleistungen bereit.",
  "Lensly reserves the right to review and verify replacement requests.": "Lensly behält sich das Recht vor, Ersatzanfragen zu prüfen und zu verifizieren.",
  "Lensly subscription (incl. replacements)": "Lensly-Abo (inkl. Ersatzleistungen)",
  "Lensly subscription (€348/yr)": "Lensly-Abo (348 €/Jahr)",
  "Lensly vs. Glasses Insurance": "Lensly vs. Brillenversicherung",
  "Lensly will confirm the selected frame before production begins.": "Lensly bestätigt den ausgewählten Rahmen vor Produktionsbeginn.",
  "Lensly will continue to work toward completion and delivery of the Customer's included eyewear benefit.": "Lensly wird weiterhin auf die Fertigstellung und Bereitstellung des im Preis inbegriffenen Brillenvorteils für den Kunden hinarbeiten.",
  "Lensly will keep the Customer informed in case of significant delays.": "Lensly will keep the Customer informed in case of significant delays.",
  "Lensly will make reasonable efforts to complete production and delivery within the stated timeframe.": "Lensly wird angemessene Anstrengungen unternehmen, um die Produktion und Lieferung innerhalb des angegebenen Zeitrahmens abzuschließen.",
  "Lensly will make reasonable efforts to process and deliver custom-made eyewear within approximately 14 to 21 days after receiving all required customer information, including valid prescription details, fitting information, and final frame approval.": "Lensly unternimmt angemessene Anstrengungen, um maßgeschneiderte Brillen innerhalb von etwa 14 bis 21 Tagen nach Erhalt aller erforderlichen Kundeninformationen, einschließlich gültiger Rezeptdetails, Passforminformationen und endgültiger Fassungsgenehmigung, zu bearbeiten und zu liefern.",
  "Lensly will make reasonable efforts to source the selected frame requested by the Customer through available supplier and retail channels to complete the eyewear order according to the Customer's selection.": "Lensly wird angemessene Anstrengungen unternehmen, um die vom Kunden gewünschte ausgewählte Fassung über verfügbare Lieferanten- und Einzelhandelskanäle zu beschaffen, um die Brillenbestellung entsprechend der Auswahl des Kunden abzuschließen.",
  "Lensly will proceed with fulfilling the confirmed eyewear benefit according to the details approved by the Customer.": "Lensly will proceed with fulfilling the confirmed eyewear benefit according to the details approved by the Customer.",
  "Lensly works with selected optical suppliers and laboratories for the production and adjustment of prescription eyewear.": "Lensly arbeitet für die Herstellung und Anpassung von Korrektionsbrillen mit ausgewählten Optiklieferanten und Laboren zusammen.",
  "Liefer- und Rechnungsadresse": "Liefer- und Rechnungsadresse",
  "Live 8-stage manufacturing and verification status for your custom eyewear.": "Live-8-stufiger Herstellungs- und Verifizierungsstatus für Ihre individuelle Brille.",
  "Live Camera": "Live Camera",
  "Live Camera Try-On": "Live Camera Try-On",
