  "Minimum term 12 months, billing €29 monthly, automatic renewal with monthly cancellation thereafter.": "Mindestlaufzeit 12 Monate, Abrechnung 29 € monatlich, danach automatische Verlängerung mit monatlicher Kündigungsmöglichkeit.",
  "Model name or number (optional)": "Model name or number (optional)",
