  "Monthly flexible": "Monatlich flexibel",
  "Moving": "Umzug",
  "My Photo": "My Photo",
  "Nach Prüfung Ihrer Sehstärkenangaben werden die Gläser passgenau für die gewählte Fassung geschliffen, entspiegelt und vor dem Versand einer sorgfältigen optischen Ausgangskontrolle unterzogen.": "Nach Prüfung Ihrer Sehstärkenangaben werden die Gläser passgenau für die gewählte Fassung geschliffen, entspiegelt und vor dem Versand einer sorgfältigen optischen Ausgangskontrolle unterzogen.",
  "Name, Vorname": "Name, Vorname",
  "Native fallback mode": "Nativer Fallback-Modus",
  "Need a recent eye test or pupillary distance measurement? Any ophthalmologist or local optometrist can issue an updated prescription pass, which you can easily photograph and upload.": "Benötigen Sie einen aktuellen Sehtest oder eine Messung des Pupillenabstands? Jeder Augenarzt oder Optiker vor Ort kann einen aktualisierten Rezeptpass ausstellen, den Sie einfach fotografieren und hochladen können.",
  "Need anti-reflective or thin lenses": "Entspiegelung oder dünne Gläser benötigt",
  "New glasses every year. No optician. ": "Neue Brille jedes Jahr. Kein Optiker. ",
  "New prescription? Another €400 out.": "Neue Sehstärke? Nochmal €400 raus.",
  "Next Contractual Possible Date": "Nächstmöglicher Vertragszeitpunkt",
  "Next possible date (contractual notice)": "Nächstmöglicher Zeitpunkt (fristgerecht)",
  "No Active Order": "Keine aktive Bestellung",
  "No Orders Yet": "Noch keine Bestellungen",
  "No Plan Subscribed": "Kein Plan abonniert",
  "No account found matching this email or tracking ID.": "Es wurde kein Konto gefunden, das dieser E-Mail-Adresse oder Tracking-ID entspricht.",
  "No account found matching this information.": "Es wurde kein Konto gefunden, das diesen Informationen entspricht.",
  "No active plan": "Kein aktiver Plan",
  "No hidden costs. No upcharges for anti-reflective coating or thin lenses. €29 once a month — that's all.": "Keine versteckten Kosten. Keine Aufpreise für Entspiegelung oder dünne Gläser. Einmal im Monat 29 € — das ist alles.",
  "No previous messages in this channel. Send your inquiry below and our opticians will respond within 2 hours.": "Keine vorherigen Nachrichten in diesem Kanal. Senden Sie unten Ihre Anfrage und unsere Optiker werden innerhalb von 2 Stunden antworten.",
  "No problem! You can submit the frame request first. Our team will verify the frame availability, and you can email your prescription or optician pass later.": "No problem! You can submit the frame request first. Our team will verify the frame availability, and you can email your prescription or optician pass later.",
  "No request found matching that Tracking ID. Please check the ID and try again.": "Keine Anfrage mit dieser Tracking-ID gefunden. Bitte überprüfe die ID und versuche es erneut.",
  "No subscriptions found.": "Keine Abonnements gefunden.",
  "Nothing extra to pay ever": "Keine versteckten Zuzahlungen",
