  "Visit any local optician or doctor for a quick measurement. It takes 2 minutes and is usually free. Then just include it in your email to us.": "Besuchen Sie einen lokalen Optiker oder Augenarzt für eine schnelle Messung. Es dauert nur 2 Minuten und ist in der Regel kostenlos. Fügen Sie den Wert einfach Ihrer E-Mail an uns bei.",
  "Visit any local optician or eye doctor for a quick measurement. Takes 2 minutes and is usually free. Then just include it in your email to us.": "Besuche einen lokalen Optiker oder Augenarzt für eine schnelle Messung. Dauert 2 Minuten und ist in der Regel kostenlos. Füge den Wert einfach deiner E-Mail an uns bei.",
