  "We source the frame for you based on your photo or screenshot. It is included in your subscription, nothing extra to pay.": "Wir beschaffen das Gestell basierend auf Ihrem Foto oder Screenshot für Sie. Es ist in Ihrem Abonnement enthalten – Sie müssen nichts extra bezahlen.",
  "We source the frame for you based on your photo or screenshot. It's included in your subscription — nothing extra to pay.": "Wir besorgen das Gestell basierend auf deinem Foto oder Screenshot für dich. Es ist in deinem Abonnement enthalten — du musst nichts extra bezahlen.",
  "We verify frame dimensions, base curve, and lens suitability for your prescription.": "Wir prüfen Fassungsmaße, Basiskurve und Eignung der Gläser für deine Sehstärke.",
  "We'll reach out within a day via email and ask for everything we need.": "Wir melden uns innerhalb eines Tages per Mail und fragen alles Nötige ab.",
  "We're a small team from Germany. The idea came up because glasses in Europe are absurdly expensive — not because they have to be, but because the market wants it that way. We work directly with certified optical labs and skip the retail markup.": "Wir sind ein kleines Team aus Deutschland. Die Idee entstand, weil Brillen in Europa absurd teuer sind — nicht weil sie es sein müssen, sondern weil der Markt es so will. Wir arbeiten direkt mit zertifizierten Optiklaboren zusammen und lassen den Händleraufschlag weg.",
  "We've received your frame details and prescription. Our optical lab is currently reviewing availability and lens compatibility.": "Wir haben deine Gestelldetails und dein Rezept erhalten. Unser Meisterlabor prüft derzeit Verfügbarkeit und Glaskompatibilität.",
  "Welcome to Lensly Care!": "Welcome to Lensly Care!",
