  "Yes. We make lenses for all common prescriptions, including high diopters and astigmatism. Drop us a message before subscribing if you're unsure.": "Ja. Wir fertigen Gläser für alle gängigen Sehstärken an, auch für hohe Dioptrien und Astigmatismus. Schreib uns kurz vor dem Abonnieren falls du unsicher bist.",
  "Yes. You choose any frame you like, from any brand, online shop, or store. Send us a photo or screenshot and we source it for you. No limitations.": "Ja. Sie können jedes beliebige Gestell wählen – von jeder Marke, aus jedem Online-Shop oder Ladengeschäft. Schicken Sie uns einfach ein Foto oder einen Screenshot und wir besorgen es für Sie. Keine Einschränkungen.",
