  "Your eyesight changes. Your style changes too. That's why we deliver a completely new pair every year — no reordering, no extra cost.": "Deine Sehstärke ändert sich. Dein Stil auch. Deshalb liefern wir dir jedes Jahr ein komplett neues Paar — kein Nachbestellen, kein Aufpreis.",
  "Your finished prescription eyewear arrives in approximately 15 days.": "Ihre fertige Korrektionsbrille kommt in ca. 15 Tagen bei Ihnen an.",
