  "Eye": "Œil",
  "Eyesight changes continuously. Frames scratch or break. Traditional retail forces large irregular upfront payments with costly repairs. Lensly bundles precision lenses, frame sourcing, and replacements into one predictable monthly plan.": "La vue change continuellement. Les cadres se rayent ou se cassent. Le commerce de détail traditionnel impose des paiements initiaux irréguliers importants et des réparations coûteuses. Lensly regroupe les verres de précision, l'approvisionnement en montures et les remplacements dans un seul forfait mensuel prévisible.",
  "Eyewear accidents happen. If you accidentally step on your frame, scratch a lens, or your optometrist diagnoses a change in cylinder power within your subscription year:": "Des accidents liés aux lunettes se produisent. Si vous marchez accidentellement sur votre monture, grattez un verre ou si votre optométriste diagnostique un changement dans la puissance du cylindre au cours de votre année d'abonnement :",
