  "Fallback Mode": "Mode de repli",
  "Fassungsbruch, tiefe Kratzer oder nachgewiesene Sehstärkenänderung innerhalb des Jahres? Ihr Tarif umfasst ein Kontingent von bis zu drei Ersatzanfragen pro Vertragsjahr gemäß Tarifbedingungen.": "Monture cassée, rayures profondes ou changement de vision avéré en l'espace d'un an ? Votre tarif comprend un quota pouvant aller jusqu'à trois demandes de remplacement par année contractuelle conformément aux conditions tarifaires.",
  "Fassungsbruch, tiefe Kratzer oder verordnete Dioptrienänderungen innerhalb des Jahres werden bis zu dreimal tarifgemäß abgedeckt.": "Fassungsbruch, tiefe Kratzer oder verordnete Dioptrienänderungen innerhalb des Jahres werden bis zu dreimal tarifgemäß abgedeckt.",
  "Feminine winged silhouette in high-gloss piano black. A sophisticated retro statement piece.": "Silhouette ailée féminine en noir piano brillant. Une pièce de déclaration rétro sophistiquée.",
  "File size exceeds 10MB limit. Please upload a smaller image.": "File size exceeds 10MB limit. Please upload a smaller image.",
  "Find optician practices in your region for exact refraction and pupillary distance (PD) measurements.": "Trouvez des cabinets d'opticiens dans votre région pour des mesures exactes de la réfraction et de la distance pupillaire (PD).",
  "Fits straight and balanced. Erasing arms updates this preview instantly.": "Fits straight and balanced. Erasing arms updates this preview instantly.",
