  "For repeated failed payment attempts caused by customer-related payment issues, Lensly may apply a reasonable processing fee of €5 per failed payment attempt after notifying the Customer.": "Pour les tentatives de paiement infructueuses répétées causées par des problèmes de paiement liés au client, Lensly peut appliquer des frais de traitement raisonnables de 5 € par tentative de paiement échouée après en avoir informé le client.",
  "Found a frame anywhere online or in-store? We check compatibility and procure it for your plan.": "Vous avez trouvé un cadre n'importe où en ligne ou en magasin ? Nous vérifions la compatibilité et l'approvisionnons pour votre plan.",
