  "Had a new eye exam or need to correct your prescription? Upload your updated pass here.": "Vous avez passé un nouvel examen de la vue ou avez besoin de corriger votre prescription ? Téléchargez votre pass mis à jour ici.",
  "Have questions about frame sourcing or prescription lenses? Our optical specialists reply within 24 hours.": "Vous avez des questions sur l'approvisionnement en montures ou sur les verres correcteurs ? Nos spécialistes en optique vous répondent sous 24 heures.",
