  "Hinweis: Die Gesellschaft befindet sich in Gründung. Umsatzsteuer-Identifikationsnummer und Handelsregistereintragung folgen nach Abschluss des Registrierungsprozesses.": "Remarque : La société est actuellement en cours de création. Le numéro d’identification TVA et l’inscription au registre du commerce suivent une fois le processus d’enregistrement terminé.",
  "How Accidental Replacements Work": "Comment fonctionnent les remplacements accidentels",
  "How Lensly achieves €29/month: We bypass expensive retail real estate and collaborate directly with certified optical finishing labs equipped with CNC edgers and digital wavefront surfacing machinery.": "How Lensly achieves €29/month: We bypass expensive retail real estate and collaborate directly with certified optical finishing labs equipped with CNC edgers and digital wavefront surfacing machinery.",
