  "I agree to the Terms of Service, the 12-month contract lock-in, and the custom-lens refund rules.": "J'accepte les conditions d'utilisation, l'engagement contractuel de 12 mois et les conditions de remboursement des verres sur mesure.",
  "I authorize recurring monthly billing of €29.": "J'autorise une facturation mensuelle récurrente de 29 €.",
  "I hereby request the legally binding cancellation of my subscription. I acknowledge the 12-month fixed minimum duration & 30-day notice periods.": "Je demande par la présente l'annulation juridiquement contraignante de mon abonnement. Je reconnais la durée minimale fixe de 12 mois et les délais de préavis de 30 jours.",
  "If a payment cannot be processed, Lensly will notify the Customer and provide an opportunity to update payment information or complete payment.": "If a payment cannot be processed, Lensly will notify the Customer and provide an opportunity to update payment information or complete payment.",
  "If subscription payments remain unpaid, Lensly may temporarily suspend benefits that require active payment, including future production and replacement services, until outstanding payments are resolved.": "Si les paiements d'abonnement restent impayés, Lensly peut suspendre temporairement les avantages qui nécessitent un paiement actif, y compris les futurs services de production et de remplacement, jusqu'à ce que les paiements impayés soient résolus.",
  "If the Customer provides a valid reason, including incorrect prescription compared with the submitted prescription, incorrect lens specifications, or confirmed fitting or frame-related production issues, Lensly will replace the affected lenses free of charge after verification.": "If the Customer provides a valid reason, including incorrect prescription compared with the submitted prescription, incorrect lens specifications, or confirmed fitting or frame-related production issues, Lensly will replace the affected lenses free of charge after verification.",
  "If there is a production error on our side we fix it completely free. Custom prescription lenses cannot be refunded once produced, but we will always make it right.": "En cas d'erreur de fabrication de notre part, nous la corrigeons gratuitement. Les verres correcteurs personnalisés ne peuvent pas être remboursés une fois produits, mais nous ferons toujours le nécessaire pour vous satisfaire.",
