  "Lensly Care": "Lensly Care",
  "Lensly Care is a vision subscription service providing customers with access to custom-made prescription eyewear benefits.": "Lensly Care is a vision subscription service providing customers with access to custom-made prescription eyewear benefits.",
  "Lensly Continuous Care:": "Lensly Continuous Care:",
  "Lensly Signature Frame Collection": "Collection de montures Lensly Signature",
  "Lensly Standard Plan": "Forfait standard Lensly",
  "Lensly Vision Care Agreement": "Lensly Vision Care Agreement",
  "Lensly is a small independent team focused on making quality prescription eyewear affordable and accessible across Europe. We work directly with certified optical labs to cut out retail markups.": "Lensly est une petite équipe indépendante dédiée à rendre les lunettes de vue de qualité abordables et accessibles dans toute l'Europe. Nous travaillons directement avec des laboratoires d'optique certifiés pour éliminer les marges des distributeurs.",
  "Lensly manufactures prescription eyewear according to the information and specifications provided by the Customer.": "Lensly manufactures prescription eyewear according to the information and specifications provided by the Customer.",
  "Lensly provides custom-made prescription eyewear through selected optical suppliers and laboratories.": "Lensly fournit des lunettes de prescription sur mesure par l'intermédiaire de fournisseurs et de laboratoires d'optique sélectionnés.",
  "Lensly provides up to three (3) approved replacement services per contract year.": "Lensly fournit jusqu'à trois (3) services de remplacement approuvés par année contractuelle.",
  "Lensly reserves the right to review and verify replacement requests.": "Lensly se réserve le droit d'examiner et de vérifier les demandes de remplacement.",
  "Lensly subscription (€348/yr)": "Abonnement Lensly (348 €/an)",
  "Lensly vs. Glasses Insurance": "Lensly vs. Assurance Lunettes",
  "Lensly will confirm the selected frame before production begins.": "Lensly confirmera la monture sélectionnée avant le début de la production.",
  "Lensly will continue to work toward completion and delivery of the Customer's included eyewear benefit.": "Lensly continuera à travailler à l’achèvement et à la fourniture de l’avantage lunettes inclus au client.",
  "Lensly will keep the Customer informed in case of significant delays.": "Lensly tiendra le Client informé en cas de retard important.",
  "Lensly will make reasonable efforts to complete production and delivery within the stated timeframe.": "Lensly fera des efforts raisonnables pour terminer la production et la livraison dans les délais indiqués.",
  "Lensly will make reasonable efforts to process and deliver custom-made eyewear within approximately 14 to 21 days after receiving all required customer information, including valid prescription details, fitting information, and final frame approval.": "Lensly will make reasonable efforts to process and deliver custom-made eyewear within approximately 14 to 21 days after receiving all required customer information, including valid prescription details, fitting information, and final frame approval.",
  "Lensly will make reasonable efforts to source the selected frame requested by the Customer through available supplier and retail channels to complete the eyewear order according to the Customer's selection.": "Lensly will make reasonable efforts to source the selected frame requested by the Customer through available supplier and retail channels to complete the eyewear order according to the Customer's selection.",
  "Lensly will proceed with fulfilling the confirmed eyewear benefit according to the details approved by the Customer.": "Lensly procédera à l'exécution de l'avantage lunettes confirmé selon les détails approuvés par le client.",
  "Lensly works with selected optical suppliers and laboratories for the production and adjustment of prescription eyewear.": "Lensly travaille avec des fournisseurs d'optique et des laboratoires sélectionnés pour la production et l'ajustement de lunettes de vue.",
  "Liefer- und Rechnungsadresse": "Adresse de livraison et de facturation",
