  "Nach Prüfung Ihrer Sehstärkenangaben werden die Gläser passgenau für die gewählte Fassung geschliffen, entspiegelt und vor dem Versand einer sorgfältigen optischen Ausgangskontrolle unterzogen.": "Après avoir vérifié les informations de votre prescription, les verres sont meulés pour s'adapter à la monture sélectionnée, antireflet et soumis à une inspection optique initiale minutieuse avant expédition.",
