  "Eye": "Ojo",
  "Eyesight changes continuously. Frames scratch or break. Traditional retail forces large irregular upfront payments with costly repairs. Lensly bundles precision lenses, frame sourcing, and replacements into one predictable monthly plan.": "La vista cambia continuamente. Los marcos se rayan o se rompen. El comercio minorista tradicional obliga a realizar grandes pagos iniciales irregulares con costosas reparaciones. Lensly incluye lentes de precisión, suministro de monturas y reemplazos en un plan mensual predecible.",
  "Eyewear accidents happen. If you accidentally step on your frame, scratch a lens, or your optometrist diagnoses a change in cylinder power within your subscription year:": "Los accidentes con gafas ocurren. Si accidentalmente pisa su montura, raya una lente o su optometrista diagnostica un cambio en la potencia del cilindro dentro de su año de suscripción:",
