  "Fassungsbruch, tiefe Kratzer oder nachgewiesene Sehstärkenänderung innerhalb des Jahres? Ihr Tarif umfasst ein Kontingent von bis zu drei Ersatzanfragen pro Vertragsjahr gemäß Tarifbedingungen.": "¿Marco roto, rayones profundos o cambio comprobado en la visión dentro del año? Tu tarifa incluye un cupo de hasta tres solicitudes de reposición por año de contrato de acuerdo con las condiciones tarifarias.",
  "Fassungsbruch, tiefe Kratzer oder verordnete Dioptrienänderungen innerhalb des Jahres werden bis zu dreimal tarifgemäß abgedeckt.": "Rotura de montura, rayones profundos o cambios de dioptrías prescritos dentro del año están cubiertos hasta tres veces de acuerdo con la tarifa.",
  "Feminine winged silhouette in high-gloss piano black. A sophisticated retro statement piece.": "Silueta femenina alada en negro piano de alto brillo. Una pieza sofisticada y retro.",
