  "Had a new eye exam or need to correct your prescription? Upload your updated pass here.": "¿Tuviste un nuevo examen de la vista o necesitas corregir tu graduación? Sube tu pase actualizado aquí.",
  "Have questions about frame sourcing or prescription lenses? Our optical specialists reply within 24 hours.": "¿Tiene preguntas sobre el abastecimiento de monturas o lentes recetados? Nuestros especialistas ópticos responden en 24 horas.",
