  "Hinweis: Die Gesellschaft befindet sich in Gründung. Umsatzsteuer-Identifikationsnummer und Handelsregistereintragung folgen nach Abschluss des Registrierungsprozesses.": "Nota: La empresa se encuentra actualmente en proceso de fundación. El número de identificación del IVA y la entrada en el registro comercial siguen una vez completado el proceso de registro.",
  "How Accidental Replacements Work": "Cómo funcionan los reemplazos accidentales",
  "How Lensly achieves €29/month: We bypass expensive retail real estate and collaborate directly with certified optical finishing labs equipped with CNC edgers and digital wavefront surfacing machinery.": "Cómo Lensly logra 29 € al mes: evitamos los costosos inmuebles minoristas y colaboramos directamente con laboratorios de acabado óptico certificados equipados con canteadoras CNC y maquinaria de revestimiento de superficies de frente de onda digital.",
