  "I agree to the Terms of Service, the 12-month contract lock-in, and the custom-lens refund rules.": "Acepto las Condiciones de servicio, el compromiso de contrato de 12 meses y las reglas de reembolso de lentes personalizadas.",
  "I authorize recurring monthly billing of €29.": "Autorizo ​​la facturación mensual recurrente de 29€.",
  "I hereby request the legally binding cancellation of my subscription. I acknowledge the 12-month fixed minimum duration & 30-day notice periods.": "Por la presente solicito la cancelación legalmente vinculante de mi suscripción. Reconozco la duración mínima fija de 12 meses y los períodos de preaviso de 30 días.",
  "If a payment cannot be processed, Lensly will notify the Customer and provide an opportunity to update payment information or complete payment.": "Si no se puede procesar un pago, Lensly notificará al Cliente y le brindará la oportunidad de actualizar la información de pago o completar el pago.",
  "If subscription payments remain unpaid, Lensly may temporarily suspend benefits that require active payment, including future production and replacement services, until outstanding payments are resolved.": "Si los pagos de suscripción siguen pendientes de pago, Lensly puede suspender temporalmente los beneficios que requieren pago activo, incluida la producción futura y los servicios de reemplazo, hasta que se resuelvan los pagos pendientes.",
  "If the Customer provides a valid reason, including incorrect prescription compared with the submitted prescription, incorrect lens specifications, or confirmed fitting or frame-related production issues, Lensly will replace the affected lenses free of charge after verification.": "Si el Cliente proporciona un motivo válido, incluida una prescripción incorrecta en comparación con la prescripción enviada, especificaciones de lentes incorrectas o problemas confirmados de ajuste o producción relacionados con la montura, Lensly reemplazará las lentes afectadas sin cargo después de la verificación.",
  "If there is a production error on our side we fix it completely free. Custom prescription lenses cannot be refunded once produced, but we will always make it right.": "Si hay un error de fabricación por nuestra parte, lo solucionamos gratis. Las lentes graduadas personalizadas no se pueden reembolsar una vez fabricadas, pero siempre buscaremos una solución.",
