  "Lensly Care": "Lensly Care",
  "Lensly Care is a vision subscription service providing customers with access to custom-made prescription eyewear benefits.": "Lensly Care es un servicio de suscripción de visión que brinda a los clientes acceso a beneficios de anteojos recetados personalizados.",
  "Lensly Continuous Care:": "Lensly Continuous Care:",
  "Lensly Signature Frame Collection": "Colección de monturas Lensly Signature",
  "Lensly Standard Plan": "Lensly Standard Plan",
  "Lensly Vision Care Agreement": "Acuerdo de cuidado de la visión de Lensly",
  "Lensly is a small independent team focused on making quality prescription eyewear affordable and accessible across Europe. We work directly with certified optical labs to cut out retail markups.": "Lensly es un pequeño equipo independiente enfocado en hacer que las gafas graduadas de calidad sean asequibles y accesibles en toda Europa. Trabajamos directamente con laboratorios ópticos certificados para eliminar los márgenes de los intermediarios.",
  "Lensly manufactures prescription eyewear according to the information and specifications provided by the Customer.": "Lensly manufactures prescription eyewear according to the information and specifications provided by the Customer.",
  "Lensly provides custom-made prescription eyewear through selected optical suppliers and laboratories.": "Lensly ofrece gafas graduadas personalizadas a través de laboratorios y proveedores ópticos seleccionados.",
  "Lensly provides up to three (3) approved replacement services per contract year.": "Lensly proporciona hasta tres (3) servicios de reemplazo aprobados por año de contrato.",
  "Lensly reserves the right to review and verify replacement requests.": "Lensly reserves the right to review and verify replacement requests.",
  "Lensly subscription (€348/yr)": "Suscripción Lensly (348 €/año)",
  "Lensly vs. Glasses Insurance": "Lensly vs. Seguro de Gafas",
  "Lensly will confirm the selected frame before production begins.": "Lensly will confirm the selected frame before production begins.",
  "Lensly will continue to work toward completion and delivery of the Customer's included eyewear benefit.": "Lensly continuará trabajando para completar y entregar el beneficio de anteojos incluido al Cliente.",
  "Lensly will keep the Customer informed in case of significant delays.": "Lensly mantendrá informado al Cliente en caso de retrasos importantes.",
  "Lensly will make reasonable efforts to complete production and delivery within the stated timeframe.": "Lensly hará esfuerzos razonables para completar la producción y la entrega dentro del plazo establecido.",
  "Lensly will make reasonable efforts to process and deliver custom-made eyewear within approximately 14 to 21 days after receiving all required customer information, including valid prescription details, fitting information, and final frame approval.": "Lensly hará esfuerzos razonables para procesar y entregar anteojos personalizados dentro de aproximadamente 14 a 21 días después de recibir toda la información requerida del cliente, incluidos los detalles válidos de la prescripción, la información de adaptación y la aprobación final de la montura.",
  "Lensly will make reasonable efforts to source the selected frame requested by the Customer through available supplier and retail channels to complete the eyewear order according to the Customer's selection.": "Lensly hará esfuerzos razonables para obtener la montura seleccionada solicitada por el Cliente a través de proveedores y canales minoristas disponibles para completar el pedido de gafas de acuerdo con la selección del Cliente.",
  "Lensly will proceed with fulfilling the confirmed eyewear benefit according to the details approved by the Customer.": "Lensly will proceed with fulfilling the confirmed eyewear benefit according to the details approved by the Customer.",
  "Lensly works with selected optical suppliers and laboratories for the production and adjustment of prescription eyewear.": "Lensly works with selected optical suppliers and laboratories for the production and adjustment of prescription eyewear.",
