  "No previous messages in this channel. Send your inquiry below and our opticians will respond within 2 hours.": "No hay mensajes anteriores en este canal. Envíe su consulta a continuación y nuestros ópticos le responderán en un plazo de 2 horas.",
  "No problem! You can submit the frame request first. Our team will verify the frame availability, and you can email your prescription or optician pass later.": "¡Ningún problema! Puede enviar la solicitud de marco primero. Nuestro equipo verificará la disponibilidad de la montura y usted podrá enviar por correo electrónico su receta o pase de óptico más tarde.",
