  "Visit any local optician or doctor for a quick measurement. It takes 2 minutes and is usually free. Then just include it in your email to us.": "Visita a cualquier óptico o médico local para una medición rápida. Lleva solo 2 minutos y suele ser gratuita. Luego inclúyela en el correo que nos envíes.",
  "Wait 2–3 years to save up money and buy again": "Esperar 2-3 años para ahorrar y comprar de nuevo",
