  "We are validating your secure checkout session and securing your signed vision contract. This will only take a moment.": "We are validating your secure checkout session and securing your signed vision contract. This will only take a moment.",
  "We ensure genuine frame availability from certified distributor channels.": "Garantizamos disponibilidad original a través de distribuidores autorizados.",
  "We immediately machine a replacement pair with your recorded prescription.": "We immediately machine a replacement pair with your recorded prescription.",
  "We purchase your frame and craft your custom lenses to specification.": "Adquirimos tu montura y elaboramos tus lentes personalizadas según tus especificaciones.",
