  "We send a replacement pair free of charge, no questions asked.": "Te enviamos un par de reemplazo gratis, sin hacer preguntas.",
  "We source the frame for you based on your photo or screenshot. It is included in your subscription, nothing extra to pay.": "Nosotros conseguimos la montura basándonos en tu foto o captura. Está incluida en tu suscripción, no tienes que pagar nada extra.",
  "We verify frame dimensions, base curve, and lens suitability for your prescription.": "Comprobamos medidas, curvatura base y grosor para tu graduación.",
  "We've received your frame details and prescription. Our optical lab is currently reviewing availability and lens compatibility.": "Hemos recibido tu montura y graduación. Nuestro laboratorio óptico está revisando disponibilidad y compatibilidad de lentes.",
  "Welcome to Lensly Care!": "Welcome to Lensly Care!",
  "Wenn Sie Auskunft über Ihre Daten wünschen oder die Löschung beantragen möchten, schreiben Sie uns an:": "Wenn Sie Auskunft über Ihre Daten wünschen oder die Löschung beantragen möchten, schreiben Sie uns an:",
  "Wenn Sie eine Fassung außerhalb unserer Signature-Kollektion wünschen, senden Sie uns einfach den Link oder einen Screenshot. Wir prüfen Verfügbarkeit und Kompatibilität mit Ihren Brillenwerten vor der Zahlung.": "Wenn Sie eine Fassung außerhalb unserer Signature-Kollektion wünschen, senden Sie uns einfach den Link oder einen Screenshot. Wir prüfen Verfügbarkeit und Kompatibilität mit Ihren Brillenwerten vor der Zahlung.",
