  "Had a new eye exam or need to correct your prescription? Upload your updated pass here.": "Had a new eye exam or need to correct your prescription? Upload your updated pass here.",
  "Have questions about frame sourcing or prescription lenses? Our optical specialists reply within 24 hours.": "Hai domande sull'approvvigionamento delle montature o sulle lenti graduate? I nostri specialisti ottici rispondono entro 24 ore.",
  "Health Insurance Notice:": "Health Insurance Notice:",
  "High-Index 1.6 UV400": "Alto indice 1.6 UV400",
  "Hinweis: Die Gesellschaft befindet sich in Gründung. Umsatzsteuer-Identifikationsnummer und Handelsregistereintragung folgen nach Abschluss des Registrierungsprozesses.": "Hinweis: Die Gesellschaft befindet sich in Gründung. Umsatzsteuer-Identifikationsnummer und Handelsregistereintragung folgen nach Abschluss des Registrierungsprozesses.",
  "How Accidental Replacements Work": "How Accidental Replacements Work",
  "How Lensly achieves €29/month: We bypass expensive retail real estate and collaborate directly with certified optical finishing labs equipped with CNC edgers and digital wavefront surfacing machinery.": "Come Lensly ottiene € 29 al mese: evitiamo costosi immobili commerciali e collaboriamo direttamente con laboratori di finitura ottica certificati dotati di molatrici CNC e macchinari per la superficie del fronte d'onda digitale.",
  "How do I get my pupillary distance measured?": "Come faccio a misurare la distanza pupillare?",
  "How do returns or refunds work?": "Come funzionano i resi o i rimborsi?",
  "How it Works": "How it Works",
  "How would you like to share your frame?": "Come vorresti condividere la tua cornice?",
  "However, Lensly may review exceptional circumstances and consider early cancellation requests on a case-by-case basis.": "However, Lensly may review exceptional circumstances and consider early cancellation requests on a case-by-case basis.",
  "I accept the minimum 12-month contract commitment.": "Accetto l'impegno contrattuale minimo di 12 mesi.",
  "I agree to the": "I agree to the",
  "I agree to the Terms of Service (AGB) & Privacy Policy.": "Accetto i Termini di servizio (AGB) e l'Informativa sulla privacy.",
  "I agree to the Terms of Service, the 12-month contract lock-in, and the custom-lens refund rules.": "Accetto i Termini di servizio, il vincolo contrattuale di 12 mesi e le regole di rimborso per le lenti personalizzate.",
  "I authorize recurring monthly billing of €29.": "Autorizzo la fatturazione mensile ricorrente di 29€.",
  "I hereby request the legally binding cancellation of my subscription. I acknowledge the 12-month fixed minimum duration & 30-day notice periods.": "Richiedo con la presente la cancellazione legalmente vincolante del mio abbonamento. Riconosco la durata minima fissa di 12 mesi e i periodi di preavviso di 30 giorni.",
  "If a payment cannot be processed, Lensly will notify the Customer and provide an opportunity to update payment information or complete payment.": "Se un pagamento non può essere elaborato, Lensly avviserà il Cliente e offrirà l'opportunità di aggiornare le informazioni di pagamento o completare il pagamento.",
  "If subscription payments remain unpaid, Lensly may temporarily suspend benefits that require active payment, including future production and replacement services, until outstanding payments are resolved.": "Se i pagamenti dell'abbonamento rimangono non pagati, Lensly può sospendere temporaneamente i vantaggi che richiedono un pagamento attivo, inclusi futuri servizi di produzione e sostituzione, fino alla risoluzione dei pagamenti in sospeso.",
  "If the Customer provides a valid reason, including incorrect prescription compared with the submitted prescription, incorrect lens specifications, or confirmed fitting or frame-related production issues, Lensly will replace the affected lenses free of charge after verification.": "Se il Cliente fornisce una ragione valida, inclusa una prescrizione errata rispetto a quella inviata, specifiche errate delle lenti o problemi confermati di adattamento o di produzione relativi alla montatura, Lensly sostituirà gratuitamente le lenti interessate dopo la verifica.",
  "If there is a production error on our side we fix it completely free. Custom prescription lenses cannot be refunded once produced, but we will always make it right.": "In caso di errore di produzione da parte nostra, lo risolveremo gratuitamente. Le lenti da vista personalizzate non sono rimborsabili una volta prodotte, ma troveremo sempre il modo di soddisfare le tue esigenze.",
  "Immediate Termination (Pending Proof)": "Risoluzione immediata (in attesa di prova)",
