  "Lens bevel & frame structural compatibility": "Compatibilità strutturale con smusso delle lenti e montatura",
  "Lens damage or scratches that materially affect clear vision.": "Danni o graffi alle lenti che influiscono materialmente sulla visione chiara.",
  "Lenses being custom surfaced.": "Lenti in lavorazione personalizzata.",
  "Lensly Care": "Lensly Care",
  "Lensly Care is a vision subscription service providing customers with access to custom-made prescription eyewear benefits.": "Lensly Care è un servizio di abbonamento per la vista che offre ai clienti l'accesso a vantaggi relativi agli occhiali da vista personalizzati.",
  "Lensly Continuous Care:": "Cura continua di Lensly:",
  "Lensly Signature Frame Collection": "Collezione di cornici firmate Lensly",
  "Lensly Standard Plan": "Piano standard Lensly",
  "Lensly Vision Care Agreement": "Contratto per la cura della vista con Lensly",
  "Lensly is a small independent team focused on making quality prescription eyewear affordable and accessible across Europe. We work directly with certified optical labs to cut out retail markups.": "Lensly è un piccolo team indipendente dedicato a rendere gli occhiali da vista di qualità convenienti e accessibili in tutta Europa. Lavoriamo direttamente con laboratori ottici certificati per eliminare i ricarichi dei rivenditori.",
  "Lensly manufactures prescription eyewear according to the information and specifications provided by the Customer.": "Lensly produce occhiali da vista secondo le informazioni e le specifiche fornite dal Cliente.",
  "Lensly provides custom-made prescription eyewear through selected optical suppliers and laboratories.": "Lensly fornisce occhiali da vista su misura attraverso fornitori e laboratori ottici selezionati.",
  "Lensly provides up to three (3) approved replacement services per contract year.": "Lensly fornisce fino a tre (3) servizi di sostituzione approvati per anno contrattuale.",
  "Lensly reserves the right to review and verify replacement requests.": "Lensly reserves the right to review and verify replacement requests.",
  "Lensly subscription (€348/yr)": "Abbonamento Lensly (348 €/anno)",
  "Lensly vs. Glasses Insurance": "Lensly vs. Assicurazione Occhiali",
  "Lensly will confirm the selected frame before production begins.": "Lensly confermerà la montatura selezionata prima dell'inizio della produzione.",
  "Lensly will continue to work toward completion and delivery of the Customer's included eyewear benefit.": "Lensly will continue to work toward completion and delivery of the Customer's included eyewear benefit.",
  "Lensly will keep the Customer informed in case of significant delays.": "Lensly manterrà informato il Cliente in caso di ritardi significativi.",
  "Lensly will make reasonable efforts to complete production and delivery within the stated timeframe.": "Lensly will make reasonable efforts to complete production and delivery within the stated timeframe.",
  "Lensly will make reasonable efforts to process and deliver custom-made eyewear within approximately 14 to 21 days after receiving all required customer information, including valid prescription details, fitting information, and final frame approval.": "Lensly compirà ogni ragionevole sforzo per elaborare e consegnare occhiali su misura entro circa 14-21 giorni dalla ricezione di tutte le informazioni richieste dal cliente, inclusi i dettagli della prescrizione valida, le informazioni sulla vestibilità e l'approvazione della montatura finale.",
  "Lensly will make reasonable efforts to source the selected frame requested by the Customer through available supplier and retail channels to complete the eyewear order according to the Customer's selection.": "Lensly farà ogni ragionevole sforzo per procurarsi la montatura selezionata richiesta dal Cliente attraverso i fornitori e i canali di vendita al dettaglio disponibili per completare l'ordine degli occhiali in base alla selezione del Cliente.",
  "Lensly will proceed with fulfilling the confirmed eyewear benefit according to the details approved by the Customer.": "Lensly procederà con l'adempimento del vantaggio di occhiali confermato secondo i dettagli approvati dal Cliente.",
  "Lensly works with selected optical suppliers and laboratories for the production and adjustment of prescription eyewear.": "Lensly works with selected optical suppliers and laboratories for the production and adjustment of prescription eyewear.",
  "Liefer- und Rechnungsadresse": "Indirizzo di consegna e fatturazione",
