  "Nach Prüfung Ihrer Sehstärkenangaben werden die Gläser passgenau für die gewählte Fassung geschliffen, entspiegelt und vor dem Versand einer sorgfältigen optischen Ausgangskontrolle unterzogen.": "Nach Prüfung Ihrer Sehstärkenangaben werden die Gläser passgenau für die gewählte Fassung geschliffen, entspiegelt und vor dem Versand einer sorgfältigen optischen Ausgangskontrolle unterzogen.",
