    "Accident & Damage Coverage": "Accident & Damage Coverage",
    "How Accidental Replacements Work": "How Accidental Replacements Work",
    "Eyewear accidents happen. If you accidentally step on your frame, scratch a lens, or your optometrist diagnoses a change in cylinder power within your subscription year:": "Eyewear accidents happen. If you accidentally step on your frame, scratch a lens, or your optometrist diagnoses a change in cylinder power within your subscription year:",
