    "Lensly Continuous Care:": "Lensly Continuous Care:",
    "Up to 3 replacement requests per contract year are included in the regular rate of €29/month (per plan terms).": "Up to 3 replacement requests per contract year are included in the regular rate of €29/month (per plan terms).",
    "Bis zu 3 Ersatzanfragen pro Vertragsjahr sind im regulären Tarif von €29/Monat enthalten (gemäß Tarifbedingungen).": "Up to 3 replacement requests per contract year are included in the regular rate of €29/month (per plan terms).",
    "Data Minimization & Compliance": "Data Minimization & Compliance",
    "German Privacy & Sensitive Medical Data Standards": "German Privacy & Sensitive Medical Data Standards",
    "Your prescription and visual health data are treated with strict purpose limitation under the European General Data Protection Regulation (GDPR / DSGVO).": "Your prescription and visual health data are treated with strict purpose limitation under the European General Data Protection Regulation (GDPR / DSGVO).",
    "Encrypted Transmission": "Encrypted Transmission",
    "All prescription documents and customer details are transmitted through TLS-encrypted channels directly to verified opticians.": "All prescription documents and customer details are transmitted through TLS-encrypted channels directly to verified opticians.",
    "Precision Manufacturing & Quality Control": "Precision Manufacturing & Quality Control",
    "Präzise Fertigung & Qualitätsprüfung": "Precision Manufacturing & Quality Control",
    "After verifying your prescription details, the lenses are custom-ground for your chosen frame, anti-reflective coated, and subjected to careful optical quality control before shipping.": "After verifying your prescription details, the lenses are custom-ground for your chosen frame, anti-reflective coated, and subjected to careful optical quality control before shipping.",
    "Nach Prüfung Ihrer Sehstärkenangaben werden die Gläser passgenau für die gewählte Fassung geschliffen, entspiegelt und vor dem Versand einer sorgfältigen optischen Ausgangskontrolle unterzogen.": "After verifying your prescription details, the lenses are custom-ground for your chosen frame, anti-reflective coated, and subjected to careful optical quality control before shipping.",
    "Prescription & PD Measurements": "Prescription & PD Measurements",
    "Need a recent eye test or pupillary distance measurement? Any ophthalmologist or local optometrist can issue an updated prescription pass, which you can easily photograph and upload.": "Need a recent eye test or pupillary distance measurement? Any ophthalmologist or local optometrist can issue an updated prescription pass, which you can easily photograph and upload.",
    "Answers & Clarity": "Answers & Clarity",
    "Frequently Asked Questions": "Frequently Asked Questions",
    "Can I really send a link or screenshot of any frame I find?": "Can I really send a link or screenshot of any frame I find?",
    "Yes. You can share a product link, model number, or clear photo from any store or designer brand. Our team checks whether genuine distributor stock is available and whether the frame dimensions support your prescription before you pay.": "Yes. You can share a product link, model number, or clear photo from any store or designer brand. Our team checks whether genuine distributor stock is available and whether the frame dimensions support your prescription before you pay.",
    "What happens before I pay?": "What happens before I pay?",
    "Nothing is charged upfront. You submit the frame details and your prescription values. We verify optical compatibility and frame availability. Only once verified do you receive a link to activate your Lensly Care subscription.": "Nothing is charged upfront. You submit the frame details and your prescription values. We verify optical compatibility and frame availability. Only once verified do you receive a link to activate your Lensly Care subscription.",
    "What if I have strong diopters or high astigmatism?": "What if I have strong diopters or high astigmatism?",
    "We fulfill prescriptions across common minus, plus, and cylinder ranges. For stronger powers (e.g. above +/-4.00 dpt or high cylinder), our lab reviews whether high-index lenses are required to keep the edge profile clean and comfortable.": "We fulfill prescriptions across common minus, plus, and cylinder ranges. For stronger powers (e.g. above +/-4.00 dpt or high cylinder), our lab reviews whether high-index lenses are required to keep the edge profile clean and comfortable.",
    "How does the annual replacement benefit work?": "How does the annual replacement benefit work?",
    "Your subscription includes up to 3 replacements per contract year for accidental breakage, severe scratches, or doctor-verified prescription changes. Simply notify our support team with photos to initiate production.": "Your subscription includes up to 3 replacements per contract year for accidental breakage, severe scratches, or doctor-verified prescription changes. Simply notify our support team with photos to initiate production.",
    "What is the contract duration and cancellation policy?": "What is the contract duration and cancellation policy?",
    "The initial contract commitment is 12 months (€29/month = €348/year). After the initial 12 months, your plan automatically renews on a flexible monthly basis, cancelable at any time with statutory 30-day notice via our online cancellation portal.": "The initial contract commitment is 12 months (€29/month = €348/year). After the initial 12 months, your plan automatically renews on a flexible monthly basis, cancelable at any time with statutory 30-day notice via our online cancellation portal.",
    "Does statutory health insurance (GKV) cover the costs?": "Does statutory health insurance (GKV) cover the costs?",
    "Übernimmt die gesetzliche Krankenkasse (GKV) die Kosten?": "Does statutory health insurance (GKV) cover the costs?",
    "Reimbursement by statutory health insurance is only possible in specific legally defined cases and depends on individual requirements. Please verify coverage with your insurance provider in advance.": "Reimbursement by statutory health insurance is only possible in specific legally defined cases and depends on individual requirements. Please verify coverage with your insurance provider in advance.",
    "Eine Erstattung durch die gesetzliche Krankenkasse ist nur in bestimmten gesetzlich vorgesehenen Fällen möglich und hängt von den individuellen Voraussetzungen ab. Bitte klären Sie die Erstattungsfähigkeit vorab mit Ihrer Krankenkasse.": "Reimbursement by statutory health insurance is only possible in specific legally defined cases and depends on individual requirements. Please verify coverage with your insurance provider in advance.",
    "How do I measure my Pupillary Distance (PD)?": "How do I measure my Pupillary Distance (PD)?",
    "Your PD is often listed on your optical pass (Brillenpass) or prescription sheet from your eye doctor or optician. Alternatively, visit any optical practice for a quick PD millimeter reading before ordering.": "Your PD is often listed on your optical pass (Brillenpass) or prescription sheet from your eye doctor or optician. Alternatively, visit any optical practice for a quick PD millimeter reading before ordering.",
    "Ready to experience hassle-free vision care?": "Ready to experience hassle-free vision care?",
    "Send us your favorite frame link or screenshot. We’ll review availability and your prescription values before you pay a single euro.": "Send us your favorite frame link or screenshot. We’ll review availability and your prescription values before you pay a single euro.",
