    "Check My Prescription & Frame": "Werte & Fassung jetzt kostenlos prüfen",
    "Explore How Lensly Works": "So funktioniert Lensly",
    "1. Customer Discovers Frame": "1. Wunschfassung entdecken",
    "Any store or brand": "Jedes Geschäft oder jede Marke",
    "Tortoiseshell Acetate": "Schildpatt-Acetat",
    "Screenshot or URL uploaded": "Screenshot oder Link übermittelt",
    "2. Lensly Lab Reviews": "2. Lensly Fachprüfung",
    "Free Check": "Kostenlose Prüfung",
    "Diopter range & index matching (1.50 - 1.67)": "Stärkenbereich & Glasindex-Abgleich (1.50 - 1.67)",
    "Lens bevel & frame structural compatibility": "Facette & strukturelle Fassungskompatibilität",
    "Distributor authenticity & availability check": "Händler-Authentizität & Verfügbarkeitsprüfung",
    "3. Lensly Delivery Commitment": "3. Lensly Lieferversprechen",
    "All-Inclusive Monthly:": "All-Inclusive monatlich:",
    "€29 / month": "29 € / Monat",
    "/ month": "/ Monat",
    "/ day": "/ Tag",
    "annual commitment": "Jahresverpflichtung",
    "Verified genuine frame": "Geprüfte Originalfassung",
    "Precision German surfaced lenses": "Präzisionsgefertigte deutsche Markengläser",
    "Up to 3 replacements per year per plan terms": "Bis zu 3 Ersatzbrillen pro Jahr gemäß Tarif",
    "The Lensly Care Model": "Das Lensly Care Modell",
    "Why Vision Care Belongs on Subscription": "Warum Sehhilfen in ein Abonnement gehören",
    "Eyesight changes continuously. Frames scratch or break. Traditional retail forces large irregular upfront payments with costly repairs. Lensly bundles precision lenses, frame sourcing, and replacements into one predictable monthly plan.": "Die Sehstärke ändert sich kontinuierlich. Fassungen verkratzen oder brechen. Der traditionelle Einzelhandel erzwingt hohe, unregelmäßige Vorauszahlungen mit teuren Reparaturen. Lensly bündelt Präzisionsgläser, Fassungsbeschaffung und Ersatz in einem planbaren Monatstarif.",
    "Pre-Payment Feasibility": "Kostenlose Machbarkeitsprüfung vor Zahlung",
    "Unlike ordinary shops where you pay first and hope for the best, Lensly checks your frame and diopters beforehand. If a frame cannot accommodate your cylinder or thickness, we inform you transparently.": "Anders als in herkömmlichen Geschäften, wo Sie zuerst zahlen und auf das Beste hoffen müssen, prüft Lensly Fassung und Dioptrien im Voraus. Falls eine Fassung Ihren Zylinder oder Glasdicke nicht aufnehmen kann, informieren wir Sie transparent.",
    "Fresh Lenses Every Single Year": "Jedes einzelne Vertragsjahr neue Gläser",
    "Every contract year you receive a complete new pair of prescription glasses with fresh anti-reflective coatings and updated diopters to ensure optimal visual health.": "In jedem Vertragsjahr erhalten Sie eine komplett neue Korrektionsbrille mit frischen Antireflex-Beschichtungen und aktualisierten Dioptrienwerten für Ihre optimale Sehkraft.",
    "Up to 3 Replacements per Contract Year": "Bis zu 3 Ersatzanfragen pro Vertragsjahr",
    "Bis zu 3 Ersatzanfragen pro Vertragsjahr": "Bis zu 3 Ersatzanfragen pro Vertragsjahr",
    "Broken frames, deep scratches, or verified prescription changes within the year? Your plan includes up to three replacement requests per contract year per plan terms.": "Fassungsbruch, tiefe Kratzer oder nachgewiesene Sehstärkenänderung innerhalb des Jahres? Ihr Tarif umfasst ein Kontingent von bis zu drei Ersatzanfragen pro Vertragsjahr gemäß Tarifbedingungen.",
    "Fassungsbruch, tiefe Kratzer oder nachgewiesene Sehstärkenänderung innerhalb des Jahres? Ihr Tarif umfasst ein Kontingent von bis zu drei Ersatzanfragen pro Vertragsjahr gemäß Tarifbedingungen.": "Fassungsbruch, tiefe Kratzer oder nachgewiesene Sehstärkenänderung innerhalb des Jahres? Ihr Tarif umfasst ein Kontingent von bis zu drei Ersatzanfragen pro Vertragsjahr gemäß Tarifbedingungen.",
    "Transparent Workflow": "Transparenter Ablauf",
    "The Lensly Customer Journey": "Die Lensly Customer Journey",
    "Designed from the ground up to eliminate hesitation. You know exactly whether your frame and lenses work before committing a single euro.": "Von Grund auf konzipiert, um Unsicherheiten zu beseitigen. Sie wissen genau, ob Fassung und Gläser harmonieren, bevor Sie einen einzigen Euro ausgeben.",
    "Discover Frame": "Fassung entdecken",
    "Find any frame you like online, in a magazine, or in a retail shop.": "Finden Sie eine beliebige Fassung online, im Magazin oder im Geschäft.",
    "Send to Lensly": "An Lensly senden",
    "Submit a screenshot, photo, or product URL through our free review tool.": "Übermitteln Sie Screenshot, Foto oder Produkt-Link über unser kostenloses Prüfformular.",
    "Prescription Review": "Werteprüfung & Abgleich",
    "Upload your prescription or optical pass. Our opticians check feasibility before you pay.": "Laden Sie Ihren Brillenpass oder Ihr Rezept hoch. Unsere Augenoptiker prüfen die Machbarkeit vor der Zahlung.",
    "Confirmation & Options": "Freigabe & Empfehlung",
    "Receive an availability report and lens recommendation directly by email.": "Erhalten Sie einen Verfügbarkeitsbericht und eine Glasempfehlung direkt per E-Mail.",
    "Simple Checkout": "Einfacher Checkout",
    "Activate your €29/month subscription with free EU delivery and complete coverage.": "Aktivieren Sie Ihr Abonnement für 29 €/Monat mit kostenlosem EU-Versand und Rundumschutz.",
    "Fulfillment & Care": "Fertigung & Betreuung",
    "Your custom eyewear is delivered upon completion, backed by up to 3 contractual replacement requests per year.": "Ihre maßgefertigte Brille wird nach Fertigstellung geliefert, begleitet von bis zu 3 vertraglichen Ersatzanfragen pro Jahr.",
    "Ihre maßgefertigte Brille wird nach Fertigstellung geliefert, begleitet von bis zu 3 vertraglichen Ersatzanfragen pro Jahr.": "Ihre maßgefertigte Brille wird nach Fertigstellung geliefert, begleitet von bis zu 3 vertraglichen Ersatzanfragen pro Jahr.",
    "Start Free Frame & Prescription Review": "Kostenlose Fassungs- & Werteprüfung starten",
    "Virtual Try-On & Digital Measurement": "Virtuelle Anprobe & Digitale Vermessung",
    "Interactive 3D Fit Preview": "Interaktive 3D-Passformvorschau",
    "Test real-time fit with your webcam or upload a photo. Adjust pupillary distance (PD) to match your facial anatomy before lab machining.": "Prüfen Sie den Echtzeit-Sitz mit Webcam oder Foto-Upload. Passen Sie die Pupillendistanz (PD) an Ihre Gesichtsanatomie vor dem Schleifen an.",
