    "Enter your Pupillary Distance (PD) for a more accurate fit. Be sure to double check your frame's dimensions before ordering your glasses.": "Geben Sie Ihre Pupillendistanz (PD) für einen präzisen Sitz ein. Prüfen Sie die Fassungsmaße vor der Bestellung sorgfältig.",
