    "Lensly Signature Frame Collection": "Lensly Signature Kollektion",
    "Don't have an external frame in mind? Choose from our signature in-house collection, all fitted with custom German-surfaced lenses.": "Keine externe Wunschfassung zur Hand? Wählen Sie aus unserer hauseigenen Signature-Kollektion mit deutschen Qualitätsgläsern.",
    "The Classic Acetate": "The Classic Acetate",
    "Handcrafted tortoiseshell frame with durable metal inner core. Suitable for all face profiles.": "Handgefertigte Schildpatt-Fassung mit robustem Metallkern. Passend für jede Gesichtsform.",
