    "Check My Prescription & Frame": "Revisar mi graduación y montura",
    "Explore How Lensly Works": "Cómo funciona Lensly",
    "1. Customer Discovers Frame": "1. El cliente descubre la montura",
    "Any store or brand": "Cualquier tienda o marca",
    "Tortoiseshell Acetate": "Acetato de carey",
    "Screenshot or URL uploaded": "Captura o enlace enviado",
    "2. Lensly Lab Reviews": "2. Revisión técnica Lensly",
    "Free Check": "Revisión gratuita",
    "Diopter range & index matching (1.50 - 1.67)": "Rango de dioptrías e índice óptico (1.50 - 1.67)",
    "Lens bevel & frame structural compatibility": "Bisel y compatibilidad estructural de montura",
    "Distributor authenticity & availability check": "Verificación de autenticidad y existencias",
    "3. Lensly Delivery Commitment": "3. Compromiso de entrega Lensly",
    "All-Inclusive Monthly:": "Todo incluido al mes:",
    "€29 / month": "29 € / mes",
    "/ month": "/ mes",
    "/ day": "/ día",
    "annual commitment": "compromiso anual",
    "Verified genuine frame": "Montura original certificada",
    "Precision German surfaced lenses": "Lentes de precisión alemana a medida",
    "Up to 3 replacements per year per plan terms": "Hasta 3 reemplazos al año según contrato",
    "The Lensly Care Model": "El modelo de cuidado Lensly",
    "Why Vision Care Belongs on Subscription": "Por qué el cuidado visual pertenece a una suscripción",
    "Eyesight changes continuously. Frames scratch or break. Traditional retail forces large irregular upfront payments with costly repairs. Lensly bundles precision lenses, frame sourcing, and replacements into one predictable monthly plan.": "La vista cambia continuamente. Las monturas se rayan o rompen. El comercio tradicional impone grandes pagos imprevistos con costosas reparaciones. Lensly combina lentes de precisión, suministro de monturas y reemplazos en un plan mensual predecible.",
    "Pre-Payment Feasibility": "Viabilidad previa al pago",
    "Unlike ordinary shops where you pay first and hope for the best, Lensly checks your frame and diopters beforehand. If a frame cannot accommodate your cylinder or thickness, we inform you transparently.": "A diferencia de las ópticas tradicionales donde pagas primero y esperas lo mejor, Lensly comprueba tu montura y dioptrías por adelantado. Si una montura no admite tu cilindro o grosor, te informamos con total transparencia.",
    "Fresh Lenses Every Single Year": "Lentes nuevas cada año de contrato",
    "Every contract year you receive a complete new pair of prescription glasses with fresh anti-reflective coatings and updated diopters to ensure optimal visual health.": "Cada año de contrato recibes unas gafas graduadas completas con nuevos tratamientos antirreflejantes y graduación actualizada para garantizar una óptima salud visual.",
    "Up to 3 Replacements per Contract Year": "Hasta 3 solicitudes de reemplazo por año de contrato",
    "Bis zu 3 Ersatzanfragen pro Vertragsjahr": "Hasta 3 solicitudes de reemplazo por año de contrato",
    "Broken frames, deep scratches, or verified prescription changes within the year? Your plan includes up to three replacement requests per contract year per plan terms.": "¿Montura rota, rayones profundos o cambio de graduación certificado durante el año? Tu plan incluye un cupo de hasta tres solicitudes de reemplazo por año según las condiciones contractuales.",
    "Fassungsbruch, tiefe Kratzer oder nachgewiesene Sehstärkenänderung innerhalb des Jahres? Ihr Tarif umfasst ein Kontingent von bis zu drei Ersatzanfragen pro Vertragsjahr gemäß Tarifbedingungen.": "¿Montura rota, rayones profundos o cambio de graduación certificado durante el año? Tu plan incluye un cupo de hasta tres solicitudes de reemplazo por año según las condiciones contractuales.",
    "Transparent Workflow": "Proceso transparente",
    "The Lensly Customer Journey": "El proceso del cliente Lensly",
    "Designed from the ground up to eliminate hesitation. You know exactly whether your frame and lenses work before committing a single euro.": "Diseñado desde el principio para eliminar cualquier duda. Sabrás con certeza si la montura y los cristales encajan antes de comprometer un solo euro.",
    "Discover Frame": "Descubrir la montura",
    "Find any frame you like online, in a magazine, or in a retail shop.": "Encuentra cualquier montura que te guste en internet, en una revista o en tienda.",
    "Send to Lensly": "Enviar a Lensly",
    "Submit a screenshot, photo, or product URL through our free review tool.": "Envía una captura de pantalla, foto o enlace de producto mediante nuestra herramienta de consulta gratuita.",
    "Prescription Review": "Revisión de la graduación",
    "Upload your prescription or optical pass. Our opticians check feasibility before you pay.": "Sube tu graduación o carnet óptico. Nuestros ópticos verificarán la viabilidad técnica antes de que pagues.",
    "Confirmation & Options": "Confirmación y opciones",
    "Receive an availability report and lens recommendation directly by email.": "Recibe un informe de disponibilidad y recomendación de lentes directamente por correo electrónico.",
    "Simple Checkout": "Contratación sencilla",
    "Activate your €29/month subscription with free EU delivery and complete coverage.": "Activa tu suscripción de 29 €/mes con envío gratuito a la UE y cobertura total.",
    "Fulfillment & Care": "Fabricación y cobertura",
    "Your custom eyewear is delivered upon completion, backed by up to 3 contractual replacement requests per year.": "Tus gafas personalizadas se entregan tras su fabricación, respaldadas por hasta 3 solicitudes contractuales de reemplazo al año.",
    "Ihre maßgefertigte Brille wird nach Fertigstellung geliefert, begleitet von bis zu 3 vertraglichen Ersatzanfragen pro Jahr.": "Tus gafas personalizadas se entregan tras su fabricación, respaldadas por hasta 3 solicitudes contractuales de reemplazo al año.",
    "Start Free Frame & Prescription Review": "Iniciar revisión gratuita de montura y graduación",
    "Virtual Try-On & Digital Measurement": "Probador virtual y medición digital",
    "Interactive 3D Fit Preview": "Vista previa interactiva de ajuste 3D",
    "Test real-time fit with your webcam or upload a photo. Adjust pupillary distance (PD) to match your facial anatomy before lab machining.": "Prueba el ajuste en tiempo real con tu cámara o subiendo una foto. Ajusta la distancia pupilar (DP) a tu fisionomía antes del mecanizado en taller.",
    "Live Camera Try-On": "Probador en vivo con cámara",
