    "Reset Position": "Restablecer posición",
    "Frame Fit": "Ajuste de montura",
    "Reset Fit": "Restablecer ajuste",
    "Enter your Pupillary Distance (PD) for a more accurate fit. Be sure to double check your frame's dimensions before ordering your glasses.": "Introduce tu distancia pupilar (DP) para un ajuste preciso. Comprueba las dimensiones de tu montura antes de realizar el pedido.",
