    "Lensly Signature Frame Collection": "Colección Signature Lensly",
    "Don't have an external frame in mind? Choose from our signature in-house collection, all fitted with custom German-surfaced lenses.": "¿No tienes una montura elegida? Elige entre nuestra colección exclusiva con lentes alemanas de alta precisión talladas a medida.",
    "The Classic Acetate": "The Classic Acetate",
    "Handcrafted tortoiseshell frame with durable metal inner core. Suitable for all face profiles.": "Montura artesanal en carey con alma metálica reforzada. Apta para cualquier perfil facial.",
    "Handcrafted Acetate": "Acetato artesanal",
