    "Lensly Signature Frame Collection": "Collezione esclusiva montature Lensly",
    "Don't have an external frame in mind? Choose from our signature in-house collection, all fitted with custom German-surfaced lenses.": "Non hai una montatura esterna in mente? Scegli dalla nostra collezione esclusiva, dotata di lenti rifinite con precisione ottica tedesca.",
    "The Classic Acetate": "The Classic Acetate",
    "Handcrafted tortoiseshell frame with durable metal inner core. Suitable for all face profiles.": "Montatura tartarugata artigianale con anima metallica rinforzata. Perfetta per tutti i profili del viso.",
    "Handcrafted Acetate": "Acetato artigianale",
    "The Modern Gold": "The Modern Gold",
    "Ultra-lightweight round stainless steel frame with subtle warm gold finish.": "Montatura rotonda ultraleggera in acciaio inossidabile con finitura dorata calda ed elegante.",
