    "Structured square frame in polished onyx resin with reinforced flexible hinges.": "Montatura squadrata decisa in resina onice lucida con cerniere flessibili e resistenti.",
    "Polished Resin": "Resina lucida",
    "The Crystal Clear": "The Crystal Clear",
